import type * as React from "react"

import { cn } from "@/lib/utils"

/**
 * 页面主容器：固定宽度 + 左右竖线。
 * 宽度可通过 CSS 变量 --grid-width 覆盖（默认 48rem）。
 */
function GridContainer({ className, ...props }: React.ComponentProps<"div">) {
  return (
    <div
      data-slot="grid-container"
      className={cn(
        "mx-auto w-full max-w-[var(--grid-width,48rem)] border-x border-edge",
        className
      )}
      {...props}
    />
  )
}

/**
 * 一行内容：底部一条横跨整个屏幕的分隔线。
 * 放在 GridContainer 内使用。
 */
function GridSection({
  className,
  topLine = false,
  ...props
}: React.ComponentProps<"section"> & { topLine?: boolean }) {
  return (
    <section
      data-slot="grid-section"
      className={cn("screen-line-bottom", topLine && "screen-line-top", className)}
      {...props}
    />
  )
}

/**
 * 斜纹分隔带：全屏宽度的斜线纹理 + 底部横线。
 */
function GridSeparator({ className, ...props }: React.ComponentProps<"div">) {
  return (
    <div
      aria-hidden
      data-slot="grid-separator"
      className={cn("screen-line-bottom h-8 w-full", className)}
      {...props}
    >
      <div className="absolute inset-y-0 -left-[100vw] w-[200vw] bg-hatch" />
    </div>
  )
}

/**
 * 分栏：栏与栏之间用虚线分隔，窄屏自动堆叠。
 */
function GridColumns({ className, ...props }: React.ComponentProps<"div">) {
  return (
    <div
      data-slot="grid-columns"
      className={cn(
        "grid grid-cols-1 divide-y divide-dashed divide-edge sm:grid-cols-2 sm:divide-x sm:divide-y-0",
        className
      )}
      {...props}
    />
  )
}

export { GridColumns, GridContainer, GridSection, GridSeparator }

"use client"

import { useMemo, useState } from "react"
import { cn } from "@/lib/utils"
import {
  Tooltip,
  TooltipContent,
  TooltipProvider,
  TooltipTrigger,
} from "@/components/ui/tooltip"

export type Contribution = { date: string; count: number; level: number }
const levels = [
  "bg-foreground/5",
  "bg-foreground/20",
  "bg-foreground/40",
  "bg-foreground/60",
  "bg-foreground/80",
]
const dayMilliseconds = 86_400_000
const dateFormatter = new Intl.DateTimeFormat("zh-CN", {
  timeZone: "UTC",
  year: "numeric",
  month: "long",
  day: "numeric",
})

/** 按真实日期排列的贡献日历；空缺日期不冒充零贡献，数据表提供非颜色读取方式。 */
export function ContributionGraph({
  data,
  className,
}: {
  /** 过去一年的每日记录，顺序任意；只绘制最后一天往前 365 天 */
  data: readonly Contribution[]
  className?: string
}) {
  const [activeDate, setActiveDate] = useState<string | null>(null)
  const { weeks, entries } = useMemo(() => {
    const valid = data
      .filter(
        (entry) =>
          /^\d{4}-\d{2}-\d{2}$/.test(entry.date) &&
          Number.isFinite(Date.parse(entry.date)),
      )
      .toSorted((a, b) => a.date.localeCompare(b.date))
    if (!valid.length) return { weeks: [], entries: [] }
    const end = Date.parse(valid[valid.length - 1].date)
    const start = end - 364 * dayMilliseconds
    const firstSunday = start - new Date(start).getUTCDay() * dayMilliseconds
    const entries = valid.filter((entry) => Date.parse(entry.date) >= start)
    const byDate = new Map(entries.map((entry) => [entry.date, entry]))
    const weeks: {
      date: string
      day: Contribution | undefined
      month: string | null
    }[][] = []
    for (let stamp = firstSunday; stamp <= end; stamp += dayMilliseconds) {
      const date = new Date(stamp).toISOString().slice(0, 10)
      const weekIndex = Math.floor(
        (stamp - firstSunday) / (7 * dayMilliseconds),
      )
      const day = new Date(stamp)
      if (!weeks[weekIndex]) weeks[weekIndex] = []
      weeks[weekIndex].push({
        date,
        day: byDate.get(date),
        month: day.getUTCDate() === 1 ? `${day.getUTCMonth() + 1}月` : null,
      })
    }
    return { weeks, entries }
  }, [data])

  if (!entries.length)
    return (
      <p className="py-8 font-mono text-xs leading-6 text-muted-foreground">
        贡献日历暂未更新。下次构建时会自动重试获取数据。
      </p>
    )
  return (
    <div className={cn("min-w-0", className)}>
      <div
        role="region"
        aria-label="过去一年的 GitHub 贡献日历，可横向滚动；方向键查看相邻日期"
        tabIndex={0}
        className="overflow-x-auto rounded-sm pb-2 focus-visible:outline-2 focus-visible:outline-ring"
      >
        <div className="flex w-max gap-2 font-mono text-[10px] text-muted-foreground">
          <div
            aria-hidden="true"
            className="grid grid-rows-[18px_repeat(7,10px)] gap-[3px]"
          >
            <span />
            <span />
            <span>一</span>
            <span />
            <span>三</span>
            <span />
            <span>五</span>
            <span />
          </div>
          <TooltipProvider delay={100}>
            <div className="flex gap-[3px]">
              {weeks.map((week) => (
                <div
                  key={week[0].date}
                  className="grid w-[10px] grid-rows-[18px_repeat(7,10px)] gap-[3px]"
                >
                  <span
                    aria-hidden="true"
                    className="relative whitespace-nowrap"
                  >
                    {week.find((entry) => entry.month)?.month}
                  </span>
                  {week.map(({ date, day }) =>
                    day ? (
                      <Tooltip key={date}>
                        <TooltipTrigger
                          render={<button type="button" />}
                          tabIndex={
                            activeDate === date ||
                            (!activeDate && date === entries[0].date)
                              ? 0
                              : -1
                          }
                          onFocus={() => setActiveDate(date)}
                          onKeyDown={(event) => {
                            const offsets: Record<string, number> = {
                              ArrowDown: 1,
                              ArrowUp: -1,
                              ArrowLeft: -7,
                              ArrowRight: 7,
                            }
                            if (!(event.key in offsets)) return
                            event.preventDefault()
                            const position = entries.findIndex(
                              (entry) => entry.date === date,
                            )
                            const next =
                              entries[
                                Math.max(
                                  0,
                                  Math.min(
                                    entries.length - 1,
                                    position + offsets[event.key],
                                  ),
                                )
                              ]
                            const region =
                              event.currentTarget.closest('[role="region"]')
                            region
                              ?.querySelector<HTMLButtonElement>(
                                `[data-date="${next.date}"]`,
                              )
                              ?.focus()
                          }}
                          data-date={date}
                          aria-label={`${dateFormatter.format(new Date(date))}：${day.count} 次贡献`}
                          className={cn(
                            "size-[10px] rounded-[2px] focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-ring",
                            levels[
                              Math.max(0, Math.min(4, Math.floor(day.level)))
                            ] ?? levels[0],
                          )}
                        />
                        <TooltipContent>
                          {dateFormatter.format(new Date(date))} ·{" "}
                          {new Intl.NumberFormat("zh-CN").format(day.count)}{" "}
                          次贡献
                        </TooltipContent>
                      </Tooltip>
                    ) : (
                      <span
                        key={date}
                        aria-hidden="true"
                        className="size-[10px]"
                      />
                    ),
                  )}
                </div>
              ))}
            </div>
          </TooltipProvider>
        </div>
      </div>
      <div
        aria-label="贡献数量由少到多"
        className="mt-3 flex items-center justify-end gap-1.5 font-mono text-[10px] text-muted-foreground"
      >
        <span>少</span>
        {levels.map((level) => (
          <span
            key={level}
            aria-hidden="true"
            className={cn("size-2.5 rounded-[2px]", level)}
          />
        ))}
        <span>多</span>
      </div>
      <details className="mt-2 text-xs text-muted-foreground">
        <summary className="w-fit cursor-pointer rounded py-1 hover:text-foreground focus-visible:outline-2 focus-visible:outline-ring">
          查看每日贡献数据
        </summary>
        <div className="mt-2 max-h-48 overflow-auto">
          <table className="w-full text-left font-mono tabular-nums">
            <caption className="sr-only">过去一年的每日贡献记录</caption>
            <thead>
              <tr>
                <th scope="col" className="py-2 font-normal">
                  日期
                </th>
                <th scope="col" className="py-2 text-right font-normal">
                  贡献次数
                </th>
              </tr>
            </thead>
            <tbody>
              {entries.map((day) => (
                <tr key={day.date}>
                  <th scope="row" className="py-1 font-normal">
                    {day.date}
                  </th>
                  <td className="text-right">
                    {new Intl.NumberFormat("zh-CN").format(day.count)}
                  </td>
                </tr>
              ))}
            </tbody>
          </table>
        </div>
      </details>
    </div>
  )
}

"use client"

import { useEffect, useState } from "react"

/** 以指定 IANA 时区显示时间，并比较访客当前的时区偏移。 */
export function LocalTime({ timeZone }: {
  /** IANA 时区名，例如 `Asia/Shanghai`，不支持 `+08:00` 这类固定偏移 */
  timeZone: string
}) {
  const [now, setNow] = useState<Date | null>(null)
  useEffect(() => {
    const update = () => setNow(new Date())
    const first = window.setTimeout(update, 0)
    const timer = window.setInterval(update, 1000)
    return () => {
      window.clearTimeout(first)
      window.clearInterval(timer)
    }
  }, [])

  if (!now)
    return (
      <span className="tabular-nums">
        --:--:-- <span className="text-muted-foreground">{"// 当地时间"}</span>
      </span>
    )
  const formatter = new Intl.DateTimeFormat("zh-CN", {
    timeZone,
    hour: "2-digit",
    minute: "2-digit",
    second: "2-digit",
    hourCycle: "h23",
  })
  const zone =
    new Intl.DateTimeFormat("en-US", { timeZone, timeZoneName: "longOffset" })
      .formatToParts(now)
      .find((part) => part.type === "timeZoneName")?.value ?? "GMT"
  const offset = zone.match(/GMT([+-])(\d{2}):(\d{2})/)
  const targetMinutes = offset
    ? (Number(offset[2]) * 60 + Number(offset[3])) *
      (offset[1] === "+" ? 1 : -1)
    : 0
  const difference = (targetMinutes + now.getTimezoneOffset()) / 60
  const comparison =
    difference === 0
      ? "与你同一时间"
      : `${difference > 0 ? "早" : "晚"} ${new Intl.NumberFormat("zh-CN", { maximumFractionDigits: 2 }).format(Math.abs(difference))} 小时`
  return (
    <span className="tabular-nums">
      <time dateTime={now.toISOString()}>{formatter.format(now)}</time>{" "}
      <span className="text-muted-foreground">
        {"// "}
        {comparison}
      </span>
    </span>
  )
}

"use client"

import { useEffect, useState } from "react"

/** 根据访客当地时间问候，首屏使用一致的静态文案以避免水合差异。 */
export function Greeting({
  fallback = "你好",
  suffix = "，很高兴在这里遇见你。",
}: {
  /** 首屏与挂载前显示的静态文案，需保持中性以避免水合差异 */
  fallback?: string
  /** 问候语之后拼接的文本，默认带一个逗号 */
  suffix?: string
}) {
  const [greeting, setGreeting] = useState(fallback)
  useEffect(() => {
    const update = () => {
      const hour = new Date().getHours()
      setGreeting(
        hour >= 5 && hour < 11
          ? "早上好"
          : hour >= 11 && hour < 14
            ? "中午好"
            : hour >= 14 && hour < 18
              ? "下午好"
              : "晚上好",
      )
    }
    const first = window.setTimeout(update, 0)
    const timer = window.setInterval(update, 60_000)
    return () => {
      window.clearTimeout(first)
      window.clearInterval(timer)
    }
  }, [])
  return (
    <>
      {greeting}
      {suffix}
    </>
  )
}

import type { ComponentProps, ReactNode } from "react"
import { cn } from "@/lib/utils"

/** 有明确名称和键盘焦点的图标链接方块。 */
export function IconLink({
  label,
  children,
  className,
  ...props
}: ComponentProps<"a"> & {
  /** 同时作为 aria-label 与 title 的可读名称，必填 */
  label: string
  children: ReactNode
}) {
  return (
    <a
      aria-label={label}
      title={label}
      className={cn(
        "inline-flex size-11 items-center justify-center rounded-md border border-edge bg-muted/30 text-muted-foreground transition-colors hover:bg-muted hover:text-foreground focus-visible:outline-2 focus-visible:outline-offset-4 focus-visible:outline-ring [&_svg]:size-5",
        className,
      )}
      {...props}
    >
      <span aria-hidden="true">{children}</span>
    </a>
  )
}

import { useId, type ReactNode } from "react"

import { GridSection } from "@/registry/ui/grid-layout/grid-layout"

import { RoleRotator } from "./role-rotator"

/** 个人封面：斜纹横幅 + 头像 + 名字 + 简介 + 职业标签轮播。放在 GridContainer 内使用。 */
export function ProfileHero({
  name,
  bio,
  roles = [],
  initials,
  avatar,
  tagline = "DESIGN · CODE · REPEAT",
  className,
}: {
  /** 显示的名字，会作为页面的 h1 */
  name: string
  /** 一两句话的自我介绍 */
  bio: string
  /** 职业标签，会依次轮播 */
  roles?: readonly string[]
  /** 未传 avatar 时，头像位置显示的缩写（1–2 个字符） */
  initials?: string
  /** 自定义头像节点，传入后替换缩写方块 */
  avatar?: ReactNode
  /** 横幅中间的装饰文字，设为空字符串可隐藏 */
  tagline?: string
  className?: string
}) {
  const titleId = useId()
  return (
    <GridSection aria-labelledby={titleId} className={className}>
      <div
        aria-hidden="true"
        className="relative flex h-32 items-center justify-center overflow-hidden bg-muted/20 sm:h-44"
      >
        <div className="absolute inset-0 bg-hatch opacity-40" />
        {tagline ? (
          <div className="relative flex items-center gap-5 font-mono text-muted-foreground/70">
            <span className="text-4xl font-extralight sm:text-5xl">{"{ "}</span>
            <span className="text-xs tracking-[0.35em]">{tagline}</span>
            <span className="text-4xl font-extralight sm:text-5xl">{" }"}</span>
          </div>
        ) : null}
      </div>
      <div className="relative flex flex-col gap-5 px-4 pb-7 sm:px-6">
        {avatar ?? (
          <div
            aria-hidden="true"
            className="relative -mt-10 flex size-20 items-center justify-center rounded-2xl border border-edge bg-background font-mono text-3xl font-medium tracking-tighter ring-4 ring-background"
          >
            {initials ?? name.slice(0, 1)}
          </div>
        )}
        <div className="flex flex-col gap-2">
          <h1
            id={titleId}
            className="text-3xl font-semibold tracking-tight sm:text-4xl"
            translate="no"
          >
            {name}
            <span className="text-primary">.</span>
          </h1>
          <p className="text-sm leading-7 text-pretty text-muted-foreground sm:text-base">
            {bio}
          </p>
          <RoleRotator roles={roles} />
        </div>
      </div>
    </GridSection>
  )
}

"use client"

import { AnimatePresence, motion, useReducedMotion } from "motion/react"
import { useEffect, useState } from "react"

/** 职业标签轮播：每 3.2 秒切换一次，可暂停；系统开启「减少动态效果」时不自动轮播。 */
export function RoleRotator({ roles }: { roles: readonly string[] }) {
  const reducedMotion = useReducedMotion()
  const [index, setIndex] = useState(0)
  const [paused, setPaused] = useState(false)
  useEffect(() => {
    if (reducedMotion || paused || roles.length < 2) return
    const timer = window.setInterval(
      () => setIndex((value) => (value + 1) % roles.length),
      3200,
    )
    return () => window.clearInterval(timer)
  }, [paused, reducedMotion, roles.length])
  if (!roles.length) return null
  return (
    <div className="flex min-h-7 items-center gap-3 font-mono text-sm text-muted-foreground">
      <span aria-hidden="true" className="text-primary">
        ↳
      </span>
      {/* 读屏一次性读出全部标签，视觉上的轮播对读屏隐藏 */}
      <span className="sr-only">{roles.join("、")}</span>
      <span aria-hidden="true" className="min-w-0">
        <AnimatePresence mode="wait" initial={false}>
          <motion.span
            key={index}
            className="inline-block"
            initial={{ opacity: 0, y: reducedMotion ? 0 : 5 }}
            animate={{ opacity: 1, y: 0 }}
            exit={{ opacity: 0, y: reducedMotion ? 0 : -5 }}
            transition={{ duration: 0.18 }}
          >
            {roles[index]}
          </motion.span>
        </AnimatePresence>
      </span>
      {roles.length > 1 ? (
        <button
          type="button"
          onClick={() => setPaused((value) => !value)}
          aria-label={paused ? "播放职业标签" : "暂停职业标签"}
          className="inline-flex size-7 items-center justify-center rounded text-xs text-muted-foreground hover:bg-muted hover:text-foreground focus-visible:outline-2 focus-visible:outline-ring motion-reduce:hidden"
        >
          <span aria-hidden="true">{paused ? "▶" : "❚❚"}</span>
        </button>
      ) : null}
    </div>
  )
}

import type { ReactNode } from "react"

import { cn } from "@/lib/utils"
import { FollowMe } from "@/registry/ui/follow-me/follow-me"
import { GridSection } from "@/registry/ui/grid-layout/grid-layout"
import { IconLink } from "@/registry/ui/icon-link/icon-link"

export type SocialLink = {
  /** 链接名称，同时作为读屏名称与悬停提示 */
  name: string
  href: string
  /** 图标节点，建议 strokeWidth={1.5} 的线性图标 */
  icon: ReactNode
}

/** 社交方块一行 + 容器外侧手写体 follow me 装饰。放在 GridContainer 内使用。 */
export function SocialFollow({
  socials,
  note = "在别处，也在这里",
  className,
}: {
  socials: readonly SocialLink[]
  /** 右侧的小字说明，设为空字符串可隐藏 */
  note?: string
  className?: string
}) {
  return (
    <GridSection
      aria-label="社交链接"
      className={cn("px-4 py-4 sm:px-6", className)}
    >
      <FollowMe />
      <div className="flex items-center justify-between gap-4">
        <div className="flex gap-2">
          {socials.map((social) => (
            <IconLink
              key={social.name}
              href={social.href}
              label={social.name}
              target="_blank"
              rel="noreferrer noopener"
            >
              {social.icon}
            </IconLink>
          ))}
        </div>
        {note ? (
          <span className="font-mono text-[10px] text-muted-foreground">
            {note} <span aria-hidden="true">↗</span>
          </span>
        ) : null}
      </div>
    </GridSection>
  )
}

import type { ReactNode } from "react"

import { GridColumns, GridSection } from "@/registry/ui/grid-layout/grid-layout"

export type Feature = {
  title: string
  description: string
  /** 图标节点，显示在标题上方的小方块里 */
  icon?: ReactNode
}

// Tailwind 需要在源码里看到完整类名，所以不能用模板字符串拼接列数
const columnClass: Record<number, string> = {
  2: "sm:grid-cols-2",
  3: "sm:grid-cols-3",
  4: "sm:grid-cols-4",
}

/** 虚线分隔的多栏介绍，窄屏自动堆叠。建议 2–4 项，放在 GridContainer 内使用。 */
export function FeatureColumns({
  title,
  items,
  id,
  className,
}: {
  /** 区块标题，例如「我在做什么」 */
  title: string
  items: readonly Feature[]
  /** 锚点 id，供页头导航跳转 */
  id?: string
  className?: string
}) {
  return (
    <GridSection id={id} className={className}>
      <div className="px-4 py-4 sm:px-6">
        <h2 className="text-sm font-medium">{title}</h2>
      </div>
      <GridColumns className={columnClass[items.length] ?? "sm:grid-cols-3"}>
        {items.map((item) => (
          <div
            key={item.title}
            className="flex min-w-0 flex-col items-start gap-3 p-4 sm:px-6 sm:pb-6"
          >
            {item.icon ? (
              <span
                aria-hidden="true"
                className="inline-flex size-8 shrink-0 items-center justify-center rounded-md border border-edge bg-muted/40 text-muted-foreground [&_svg]:size-4"
              >
                {item.icon}
              </span>
            ) : null}
            <h3 className="text-sm font-medium tracking-tight">{item.title}</h3>
            <p className="text-sm leading-7 text-muted-foreground">
              {item.description}
            </p>
          </div>
        ))}
      </GridColumns>
    </GridSection>
  )
}

import { Bot, Code2, Globe, Layers, Mail, Server } from "lucide-react"
import type { Metadata } from "next"
import type { ReactNode } from "react"

import { FeatureColumns } from "@/registry/blocks/feature-columns/feature-columns"
import { ProfileHero } from "@/registry/blocks/profile-hero/profile-hero"
import {
  GitHubMark,
  XMark,
} from "@/registry/blocks/social-follow/brand-icons"
import { SocialFollow } from "@/registry/blocks/social-follow/social-follow"
import { AboutSection } from "@/registry/templates/portfolio-grid/components/portfolio/about-section"
import { SiteFooter } from "@/registry/templates/portfolio-grid/components/portfolio/site-footer"
import { SiteHeader } from "@/registry/templates/portfolio-grid/components/portfolio/site-header"
import { StackSection } from "@/registry/templates/portfolio-grid/components/portfolio/stack-section"
import {
  siteConfig,
